import{_ as o,o as a,c as d,ag as e}from"./chunks/framework.KxDd3USm.js";const p=JSON.parse('{"title":"07.5 正规式与正规集 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"07-程序设计语言基础/05-正规式.md","filePath":"07-程序设计语言基础/05-正规式.md"}'),c={name:"07-程序设计语言基础/05-正规式.md"};function r(b,t,s,n,l,i){return a(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="_07-5-正规式与正规集-★★★" tabindex="-1">07.5 正规式与正规集 ★★★ <a class="header-anchor" href="#_07-5-正规式与正规集-★★★" aria-label="Permalink to &quot;07.5 正规式与正规集 ★★★&quot;">​</a></h1><p><strong>动机</strong>：词法分析阶段要识别&quot;什么样的字符串算一个标识符、什么样的算一个整数&quot;——这种<strong>单词的模式</strong>就用正规式（正则表达式）描述。它是描述字符串集合的最简工具。</p><h3 id="_6-1-三种运算与优先级" tabindex="-1">6.1 三种运算与优先级 <a class="header-anchor" href="#_6-1-三种运算与优先级" aria-label="Permalink to &quot;6.1 三种运算与优先级&quot;">​</a></h3><p>正规式只有三种基本运算（按优先级从高到低）：</p><table tabindex="0"><thead><tr><th>运算</th><th>符号</th><th>含义</th><th>例</th></tr></thead><tbody><tr><td><strong>闭包</strong></td><td><code>*</code></td><td>重复 0 次或多次（优先级<strong>最高</strong>）</td><td><code>a*</code> = {ε, a, aa, aaa, …}</td></tr><tr><td><strong>连接</strong></td><td><code>·</code>（常省略）</td><td>依次拼接（次高）</td><td><code>ab</code> = {ab}</td></tr><tr><td><strong>或</strong></td><td>`</td><td>`</td><td>二选一（<strong>最低</strong>）</td></tr></tbody></table><p><strong>公式三件套（以 <code>(a|b)*</code> 为例）</strong>：① 通用形式——闭包作用于括起来的整体，表示括号内串的任意次拼接；② 代入算例——<code>(a|b)*</code> = {ε, a, b, ab, ba, aab, abb, …}，即<strong>所有由 a、b 组成的串（含空串）</strong>；③ 手算口诀——先算 <code>*</code>（闭包），再算连接，最后算 <code>|</code>；想改变顺序就加括号。</p><p><strong>常用正规式速查表（背熟，考题基本不出这张表）</strong>：</p><table tabindex="0"><thead><tr><th>正规式</th><th>表示的正规集</th></tr></thead><tbody><tr><td><code>ab</code></td><td>仅 {ab}</td></tr><tr><td>`a</td><td>b`</td></tr><tr><td><code>a*</code></td><td>{ε, a, aa, aaa, …}（任意多个 a，含空串）</td></tr><tr><td>`(a</td><td>b)*`</td></tr><tr><td>`a(a</td><td>b)*`</td></tr><tr><td>`(a</td><td>b)*abb`</td></tr><tr><td>`(a</td><td>b)*aa(a</td></tr></tbody></table><p><strong>反例演示（三组经典混淆，逐组看会错在哪）</strong>：</p><ol><li><code>ab*</code> ≠ <code>(ab)*</code>。<code>ab*</code> 中 <code>*</code> 只作用于 b（闭包优先级最高）：{a, ab, abb, abbb, …}——<strong>一个 a 后跟任意多个 b</strong>；<code>(ab)*</code> 是 {ε, ab, abab, …}。若把 <code>ab*</code> 误当成 <code>(ab)*</code>，就会得出&quot;<code>abb</code> 属于 <code>(ab)*</code>&quot;的错误结论——按 <code>(ab)*</code> 逐块切分 <code>abb</code>：第一块 ab，剩下 <code>b</code> 不够一块，切不动 → 不属于。</li><li><code>a|b*</code> ≠ <code>(a|b)*</code>。<code>a|b*</code> = {a} ∪ {ε, b, bb, …}——<strong>单个 a，或若干个 b</strong>；绝没有 ab、ba 这种混合串。</li><li>「以 abb 结尾」≠「含有 abb」。<code>(a|b)*abb</code> 要求串<strong>最后三个字符</strong>恰好是 abb；若多写一段成 <code>(a|b)*abb(a|b)*</code>，就放宽成&quot;中间只要出现过 abb&quot;——此时 <code>abba</code>（以 a 结尾）也会被匹配。边界条件差一段闭包，集合就完全不同。</li></ol><h3 id="_6-2-专题-给正规式判串-完整判定步骤" tabindex="-1">6.2 专题：给正规式判串（完整判定步骤） <a class="header-anchor" href="#_6-2-专题-给正规式判串-完整判定步骤" aria-label="Permalink to &quot;6.2 专题：给正规式判串（完整判定步骤）&quot;">​</a></h3><p><strong>考场四步法</strong>：</p><ol><li><strong>翻译</strong>：把正规式翻译成大白话——&quot;以什么开头 / 以什么结尾 / 中间任意 / 至少含什么&quot;。</li><li><strong>首尾筛查</strong>：先用开头、结尾条件快速淘汰选项（最快）。</li><li><strong>分块回代</strong>：对存活选项，把串按正规式结构<strong>切分</strong>——闭包部分逐字符核对是否都在字母表内，<code>|</code> 部分逐位二选一。</li><li><strong>反向验证</strong>：把选中的串按&quot;开头块 + 闭包块 + 结尾块&quot;重新拆一遍，确认每块都能对上号，且没有剩余字符没归属。</li></ol><p><strong>例（完整演算）</strong>：正规式 <code>r = (a|b)*aa(a|b)*</code>，判断哪个串属于 L(r)。</p><ol><li>翻译：所有<strong>含有连续两个 a（子串 aa）</strong> 的 a、b 串。</li><li>首尾筛查：首尾无限制（两端都是 <code>(a|b)*</code>），此步淘汰不了，直接进第 3 步。</li><li>分块回代： <ul><li><code>ababa</code>：逐字符找 aa——a、ab、aba…均无相邻两个 a → 不属于 ✗</li><li><code>baab</code>：中间 b<strong>aa</strong>b，含 aa → 候选 ✓</li><li><code>abab</code>：无 aa ✗</li><li><code>abba</code>：无 aa ✗</li></ul></li><li>反向验证：<code>baab</code> = <code>(a|b)*</code> 取 b ＋ <code>aa</code> ＋ <code>(a|b)*</code> 取 b，三块拼回恰好是 baab，无剩余字符 ✓。</li></ol><p><strong>结论：只有 baab 属于 L(r)</strong>。注意第 3 步找&quot;连续 aa&quot;是看<strong>相邻</strong>两个字符，别隔位看。</p><p><strong>给串选正规式</strong>（反过来问）同样用四步法：先看待匹配串的结构特征（开头/结尾/含什么），再逐个选项检查——特别警惕&quot;形似但范围不同&quot;的选项，用上面第 6.1 节的反例 1、2 的切分法排除。</p><h3 id="_6-3-两类真题变体-由式找规律、由语言选式" tabindex="-1">6.3 两类真题变体：由式找规律、由语言选式 <a class="header-anchor" href="#_6-3-两类真题变体-由式找规律、由语言选式" aria-label="Permalink to &quot;6.3 两类真题变体：由式找规律、由语言选式&quot;">​</a></h3><p><strong>变体一：给正规式，问整个集合的共同特征。</strong></p><p>例：<code>0*(10*1)*0*</code> 表示什么？</p><ol><li>最外两段 <code>0*</code> 允许开头、结尾出现任意多个 0；</li><li>中间每个 <code>10*1</code> 块固定贡献 <strong>两个 1</strong>，两者之间可夹任意多个 0；</li><li>整块再取 <code>*</code>，可以重复 0 次、1 次、2 次……；</li><li>因而 1 的总数只能是 0、2、4、6……，即<strong>1 出现偶数次的所有 0、1 串</strong>。</li></ol><p>代串验证：<code>000</code> 取中间块 0 次，属于；<code>101</code> 有两个 1，属于；<code>11001</code> 有三个 1，不属于。反例：不能把它误读成“长度为偶数”，<code>101</code> 长度 3，却有两个 1，仍属于该语言。</p><p><strong>变体二：给语言定义，选择正规式。</strong></p><p>“所有至少含一个 1 的 0、1 串”可写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0*1(0|1)*</span></span></code></pre></div><p>第一个固定 <code>1</code> 保证“至少一个”；它前面只能是 0，所以由 <code>0*</code> 承担；第一个 1 之后可以再出现任意 0/1，由 <code>(0|1)*</code> 承担。也可写成 <code>(0|1)*1(0|1)*</code>，两者都描述“某处至少出现一个 1”，但选择题以选项实际给法为准。</p><p><strong>排除法</strong>：为每个候选式各找一个“应当接受的串”和“应当拒绝的串”。例如“至少一个 1”必须接受 <code>1、001、1010</code>，必须拒绝 <code>ε、0、000</code>；一个选项只要在这几条上出错即可淘汰，不必穷举整个语言。</p><p><strong>应试动作</strong>：背熟速查表 + 三组反例。考场上题干给一个正规式四个串，30 秒流程：翻译成大白话 → 首尾筛 → 存活者分块回代 → 反向拼回验证。若问集合规律，就数每个重复块固定贡献几个字符；若给语言选式，就用“应接收/应拒绝”的最小测试串排除。&quot;给状态图写正规式&quot;用第七节的方法。</p>',28)])])}const h=o(c,[["render",r]]);export{p as __pageData,h as default};
